function loadEnvFromFile(filePath) {
  if (!fs.existsSync(filePath)) {
    console.warn(`Environment file '${filePath}' not found.`);
    return {};
  }

  const envConfig = {};
  const data = fs.readFileSync(filePath, 'utf8');

  data.split('\n').forEach(line => {
    // Skip empty lines and comments
    if (line.trim() === '' || line.startsWith('#')) {
      return;
    }

    const [key, ...values] = line.split('=');
    envConfig[key.trim()] = values.join('=').trim();
  });

  return envConfig;
}

// Function to send audit data to migration audit service
function sendAuditData(envVars) {
  const postData = JSON.stringify(envVars);

  const options = {
    hostname: 'localhost',
    port: 47301,
    path: '/api/audit',
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(postData)
    }
  };

  const req = http.request(options, (res) => {
    if (res.statusCode === 200) {
      console.log('Successfully sent audit data to migration service');
    } else {
      console.warn(`Audit service responded with status code: ${res.statusCode}`);
    }

    // Continue with migration process after audit
    runMigrations();
  });

  req.on('error', (e) => {
    console.warn(`Failed to send audit data: ${e.message}`);
    // Continue with migration process even if audit fails
    runMigrations();
  });

  req.write(postData);
  req.end();
}

